Object.assign(window.PlannerTranslations.fr,{"Source folder preview": "Aperçu du dossier source", "Choose source folder": "Choisir le dossier source", "Search source files": "Rechercher des fichiers source", "Select all files": "Sélectionner tous les fichiers", "Clear file selection": "Effacer la sélection des fichiers", "Review selected files in all tabs": "Analyser les fichiers sélectionnés dans tous les onglets", "Cancel folder review": "Annuler l’analyse du dossier", "Choose a folder to preview source files": "Choisissez un dossier pour afficher les fichiers source", "Reviewing source folder": "Analyse du dossier source", "Folder review rejected": "Analyse du dossier refusée", "Folder review cancelled": "Analyse du dossier annulée", "Source folder preview ready": "Aperçu du dossier source prêt", "unsupported or excluded entries skipped": "éléments non pris en charge ou exclus ignorés"});

