Object.assign(window.PlannerTranslations.de,{"Game controls": "Spielsteuerung", "Plan here. Approve game actions in Reforger.": "Hier planen. Spielaktionen in Reforger freigeben.", "Game control tasks": "Aufgaben der Spielsteuerung", "Deploy": "Einsetzen", "Orders": "Befehle", "Server": "Server", "Select units": "Einheiten wählen", "Review here": "Hier prüfen", "Approve in Reforger": "In Reforger freigeben", "Plan files": "Plandateien", "Help & Sarge": "Hilfe und Sarge", "tracked": "erfasst", "Pilot": "Pilot"});

